function runNetworkChecks(id){const d=E.find(s,id);if(!d)return;let stopped=false,last=null;
 const tests=[['Power & boot','A powered device needs working hardware and an operating system before network tests can help.',()=>E.ready(s,id)],['Local connection',d.network.wifi?'First join the correct radio network with the correct passphrase. An address comes next.':'A seated plug is not enough: the adapter and the device at the other end must be ready.',()=>{if(d.network.wifi)return E.wifiAssociation(s,id);const ports=['eth',...(d.nic==='10g'?['sfp']:[])].map(p=>portState(s,id,p));const p=ports.find(p=>p.live)||ports[0];return {ok:!!p.live,why:p.why||'Check the Ethernet cable and both endpoints.'};}],['IP address & subnet','DHCP supplies settings, or you enter a unique static address. The mask identifies your local network.',()=>E.network(s,id)],['Gateway & public IP','The router forwards to other networks. This private IPv4 lab also needs NAT and a working provider path. Ping checks ICMP, not DNS or a web page.',()=>E.test(s,id,'internet','ping')],['DNS name lookup','The name directory turns example.com into a teaching IP address. The router can forward this lookup.',()=>E.lookupDNS(s,id)],['TCP, TLS & the web page','TCP (Transmission Control Protocol) opens the connection to port 443. TLS (Transport Layer Security) protects the HTTPS request and reply. This model uses TCP-based HTTPS; HTTP/3 is outside its scope.',()=>E.test(s,id,'internet','https')]];
 const steps=tests.map(([title,meaning,run])=>{if(stopped)return {title,meaning,status:'waiting',why:'Fix the earlier check, then run the sequence again.'};const r=run();last=r;if(!r.ok)stopped=true;return {title,meaning,status:r.ok?'ok':'error',why:r.why};});
 netCheck={id,steps};if(last)testResult(last);renderNetworkWorkshop();
}

let vmFeedback=null,vmOwner=null,vmLastTest=null;
const vmModes={external:{title:'External · reach the LAN',body:'Guests connect through the host’s physical network adapter. A working router and Internet path are still needed to reach the web.',host:true,lan:true},internal:{title:'Internal · host + guests',body:'Guests can talk to each other and the host. This lab has no NAT on this switch, so it has no path to the physical LAN or Internet.',host:true,lan:false},private:{title:'Private · guests only',body:'Guests on this host can talk to each other. The host operating system and physical LAN are outside this switch.',host:false,lan:false}};
