 const check=E.createVM({...s,vms:[...s.vms]},h?.id,$('vmName').value,ram,cpu,disk,$('vmMode').value);$('createVm').disabled=!check.ok;$('vmCreateHint').textContent=check.ok?'Ready to create. The next step is installing a guest operating system.':check.message;
 fillKeep('vmClient',s.devices.filter(d=>d.type==='laptop').map(d=>[d.id,d.name]));
 $('vmFeedback').textContent=vmFeedback?.text||'Follow the numbered steps on each VM. All controls run in the learning simulation.';$('vmFeedback').className='vm-feedback '+(vmFeedback?(vmFeedback.ok?'ok':'error'):'');
 $('vmList').innerHTML=s.vms.length?s.vms.map(v=>{const r=E.vmStatus(s,v),host=E.find(s,v.host),hostReady=E.vmHostReady(s,v.host).ok;return `<article class="vm-card vm-console"><header><div><span class="eyebrow">GUEST ON ${esc(host?.name||'Missing host')}</span><h3>${esc(v.name)}</h3></div><span class="vm-state ${r.ok?'running':''}">${r.ok?'Running':v.running?'Blocked':'Stopped'}</span></header><div class="vm-mini-screen ${r.ok?'online':''}"><span aria-hidden="true">▣</span><b>${!hostReady?'Host unavailable':!v.os?'No guest OS':r.ok?'Guest OS running':'Ready to start'}</b><small>${v.ram} GB RAM · ${v.cpu} vCPUs · ${v.disk} GB disk</small></div><ol class="vm-lifecycle"><li class="done">Create</li><li class="${v.os?'done':''}">Install OS</li><li class="${r.ok?'done':''}">Start</li><li class="${r.ok&&v.service?'done':''}">Web service</li></ol><p class="vm-live-status">${esc(r.why)}</p><div class="vm-actions"><button data-osdesktop="${v.id}" ${r.ok?'':'disabled'}>Open Ubuntu desktop</button><button data-vmos="${v.id}" ${v.os||!hostReady?'disabled':''}>${v.os?'✓ Guest OS installed':'1 · Install guest OS'}</button><button data-vmrun="${v.id}" ${!v.running&&(!v.os||!hostReady)?'disabled':''}>${v.running?'Stop VM':'2 · Start VM'}</button><button data-vmservice="${v.id}" ${!r.ok?'disabled':''}>${v.service?'Disable web service':'3 · Enable web service'}</button></div><label>Network for this VM<select data-vmmode="${v.id}">${Object.entries(vmModes).map(([k,m])=>opt(k,m.title,v.mode)).join('')}</select></label>${vmNetworkMap(v.mode)}<button class="vm-test-button" data-vmtest="${v.id}" ${$('vmClient').value?'':'disabled'}>4 · Test HTTPS from selected laptop</button>${vmLastTest?.id===v.id?`<div class="vm-feedback ${vmLastTest.result.ok?'ok':'error'}" role="status"><b>${vmLastTest.result.ok?'PASS':'CHECK THIS'}</b><p>${esc(vmLastTest.result.why)}</p><details><summary>Follow the test path</summary><ol>${(vmLastTest.result.trace||[]).map(t=>'<li>'+esc(t)+'</li>').join('')}</ol></details></div>`:''}<details><summary>Manage guest</summary><p>Removing this simulated VM releases its reserved resources.</p><button data-vmdelete="${v.id}">Remove VM</button></details></article>`}).join(''):'<div class="vm-empty"><b>No virtual machines yet.</b><p>Check your host above, choose resources, and create your first guest.</p></div>';
