function renderBottom(){if(!$('cloudBackupSource')){const label=document.createElement('label');label.innerHTML='Backup source<select id="cloudBackupSource"></select>';$('cloudBackup').before(label);}fillKeep('cloudBackupSource',s.devices.filter(d=>['server','nas'].includes(d.type)).map(d=>[d.id,d.name]));const ds=s.devices.filter(d=>['laptop','server','nas'].includes(d.type));fillKeep('testSource',ds.map(d=>[d.id,d.name]));fillKeep('testTarget',[['internet','Internet test page'],['cloud','Cloud service'],...ds.map(d=>[d.id,d.name]),...s.vms.map(v=>[v.id,v.name+' · VM (HTTPS test)'])]);fillKeep('vmHost',E.ofType(s,'server').map(d=>[d.id,d.name]));renderVMWorkshop();$('cloudModel').value=s.cloud.model;$('cloudService').value=s.cloud.service;$('cloudMeaning').textContent=s.cloud.account?cloudExplanation(s.cloud.model,s.cloud.service):'Choose models to see who operates each layer. This creates no real cloud account.';$('backupStatus').textContent=s.cloud.backup?`Simulated recovery copy recorded from ${s.cloud.sourceName}. ${s.cloud.verified?'Recovery record verified.':'Verify it before relying on it.'}`:'No off-site recovery copy yet.';if(!$('verifyBackup')){const b=document.createElement('button');b.id='verifyBackup';b.textContent='Verify recovery copy';$('backupStatus').after(b);b.onclick=()=>{if(!s.cloud.backup)return toast('Run a backup first.',false);s.cloud.verified=true;result({ok:true,message:'Recovery record verified. This confirms the teaching snapshot, not a real file restore.'})};}}
function cloudExplanation(m,v){return ({public:'Public: a provider serves many customers.',private:'Private: cloud infrastructure is exclusive to one organization.',hybrid:'Hybrid: distinct private and public cloud environments are connected.',community:'Community: organizations share cloud infrastructure for common needs.'}[m]||'')+' '+({iaas:'IaaS: provider manages physical infrastructure; you manage guest OS and apps.',paas:'PaaS: provider manages the platform; you deploy and manage your app.',saas:'SaaS: provider runs the app; you manage your data and access.'}[v]||'');}
function render(){renderCoach();renderScene();renderInspector();renderCables();renderBottom();$('mission').value=s.mission;$('powerOutage').textContent=s.outage?'Restore wall power':'Simulate wall-power loss';$('safetyTools').innerHTML=check('toolMat',s.safety.mat,'Grounded ESD mat')+check('toolStrap',s.safety.strap,'ESD wrist strap')+check('toolClear',s.safety.clearance,'Airflow and workspace clear')+`<p class="small">${term('esd','Safe component handling')}</p>`;for(const [id,k] of [['toolMat','mat'],['toolStrap','strap'],['toolClear','clearance']])$(id).onchange=e=>{s.safety[k]=e.target.checked};hardware?.refresh();desktop?.refresh();renderNetworkWorkshop();studio?.refresh();learning?.refresh();presentation?.refresh();challenges?.refresh();}
