function troubleStarter(){for(const type of ['pdu','ont','router','switch','laptop'])E.addDevice(s,type);const p=by('pdu'),o=by('ont'),r=by('router'),w=by('switch'),l=by('laptop');E.connect(s,'wall','out1',p.id,'ac','power',6);[o,r,w,l].forEach((d,i)=>E.connect(s,p.id,'out'+(i+1),d.id,'ac','power',6));E.connect(s,'isp','fiber',o.id,'fiber','sc',20);E.connect(s,o.id,'lan',r.id,'wan','cat5e',6);E.connect(s,r.id,'lan1',w.id,'p1','cat5e',6);E.connect(s,l.id,'eth',w.id,'p2','cat5e',6);s.links.at(-1).broken=true;s.devices.forEach(d=>d.on=true);r.router.dns='192.168.50.250';s.selected=l.id;}
function readFoundations(){try{const x=JSON.parse(localStorage.getItem(foundationKey)||'{}');return x&&typeof x==='object'?x:{}}catch{return {}}}
function saveFoundation(){const advanced=makeFoundation(s,'server'),made=advanced.ok?advanced:makeFoundation(s,'network'),kind=made.kind||'network';if(!made.ok)return made;try{const records=readFoundations();records[kind]=made.state;localStorage.setItem(foundationKey,JSON.stringify(records));return {ok:true,kind,message:'Validated '+kind+' foundation saved in this browser.'}}catch{return {ok:false,issues:['Browser storage is unavailable. Export your build instead.']}}}
function automaticFoundation(){if([22,37].includes(s.walkthrough?.index))saveFoundation();}
function foundationStatus(){const records=readFoundations();return {network:!!(records.network||records.server),server:!!records.server};}
function start(m,fromFoundation=false){ux?.stop();if(fromFoundation){const r=checkpointStart(m,readFoundations());if(!r.ok){toast(r.issues.join(' '),false);return;}s=validateSave(r.state);}else s=E.fresh(m);if(m==='trouble'&&!fromFoundation)troubleStarter();$('goalResult').textContent='';$('testResult').innerHTML='<p>Choose endpoints and send a test to see what happens.</p>';render();world?.view('wide');ux?.onLesson();}
