document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;const a=b.dataset;if(a.osdesktop){desktop?.open(a.osdesktop);return;}if(a.term){e.preventDefault();showTerm(a.term)}if(a.close)$(a.close).close();if(a.add){const r=E.addDevice(s,a.add);if(r.ok)s.selected=r.id;result(r)}if(a.device){s.selected=a.device;renderScene();renderInspector();hardware?hardware.open(a.device):ux?.revealInspector()}if(a.view){s.view=a.view;renderScene()}if(a.unplug){s.links=s.links.filter(l=>l.id!==a.unplug);result({ok:true,message:'Cable disconnected.'})}if(a.break){const l=s.links.find(l=>l.id===a.break);l.broken=!l.broken;result({ok:true,message:l.broken?'Cable fault introduced. Test which services lose their path.':'Cable repaired.'})}if(a.drive!==undefined){const d=E.find(s,s.selected),disk=d.disks[Number(a.drive)];if(!disk.failed){disk.failed=true;result({ok:true,message:'Disk failure simulated. '+E.raidStatus(d).message})}else{if(!E.powered(s,d.id)||!E.raidStatus(d).ok)return toast('Rebuild needs a powered controller and enough surviving redundancy. This array needs recovery or a fresh lab.',false);const rebuildOwner=s;b.disabled=true;b.textContent='Rebuilding…';toast('Replacing with an equal-capacity member and rebuilding from surviving redundancy…');setTimeout(()=>{if(s!==rebuildOwner||E.find(s,d.id)!==d||!d.disks.includes(disk))return;if(!E.powered(s,d.id)||!E.raidStatus(d).ok)return result({ok:false,message:'Rebuild stopped: power or surviving array became unavailable.'});disk.failed=false;d.rebuilds=(d.rebuilds||0)+1;result({ok:true,message:'Rebuild completed. '+E.raidStatus(d).message})},2500)}}const vid=a.vmos||a.vmrun||a.vmservice||a.vmtest||a.vmdelete;if(vid){const v=s.vms.find(x=>x.id===vid);if(!a.vmtest&&controlCenter){const access=controlCenter.vmAccess(v.host);if(!access.ok){vmOutcome(access);return;}}if(a.vmos)vmOutcome(E.vmAction(s,vid,'install'));if(a.vmrun)vmOutcome(E.vmAction(s,vid,v.running?'stop':'start'));if(a.vmservice)vmOutcome(E.vmAction(s,vid,'service'));if(a.vmtest){const r=E.testVM(s,$('vmClient').value,v.id);networkResult({source:$('vmClient').value,target:v.id,protocol:'https',vm:true},r);vmFeedback={ok:r.ok,text:v.name+': '+r.why};vmLastTest={id:v.id,result:r};renderVMWorkshop();}if(a.vmdelete){s.vms=s.vms.filter(x=>x.id!==vid);vmOutcome({ok:true,message:'VM resources released.'})}}});
document.addEventListener('change',e=>{if(e.target.dataset.vmmode){const v=s.vms.find(v=>v.id===e.target.dataset.vmmode);if(controlCenter){const access=controlCenter.vmAccess(v.host);if(!access.ok){vmOutcome(access);return;}}v.mode=e.target.value;vmOutcome({ok:true,message:'Virtual switch changed. Test isolation again.'})}});
