$('goalPrev').onclick=()=>{s.step=Math.max(0,s.step-1);$('goalResult').textContent='';renderCoach();ux?.onLesson()};$('goalNext').onclick=()=>{const steps=missions[s.mission].steps,g=steps[s.step];if(!g.pass()){studio?.sound('error');$('goalResult').textContent='Keep building: this step is not complete yet. Open “Show exact steps & why” and use readiness checks.';return;}if(s.step===steps.length-1){studio?.sound('complete');$('goalResult').textContent='Lab complete! Keep experimenting, export this build, or choose another configuration.';return;}studio?.sound('connect');s.step++;$('goalResult').textContent='Step checked. You are ready for the next task.';renderCoach();ux?.onLesson()};$('coachVoice').onclick=()=>{if(!('speechSynthesis'in window))return toast('This browser does not offer narration.',false);speechSynthesis.cancel();const g=missions[s.mission].steps[s.step],u=new SpeechSynthesisUtterance(g.title+'. '+g.body+' '+g.help);u.rate=.9;speechSynthesis.speak(u)};$('stopVoice').onclick=()=>window.speechSynthesis?.cancel();$('powerOutage').onclick=()=>{s.outage=!s.outage;result({ok:true,message:s.outage?'Wall power lost. Only correctly connected, powered UPS-backed equipment can continue.':'Wall power restored.'})};$('auditLab').onclick=()=>{$('testResult').innerHTML='<h3>Readiness report</h3>'+E.health(s).map(r=>`<p><b>${esc(r.name)}:</b> ${r.ok?'READY':esc(r.why)}</p>`).join('');};$('runTest').onclick=()=>{const spec={source:$('testSource').value,target:$('testTarget').value,protocol:$('testProtocol').value};if(desktop?.runNetworkTest)desktop.runNetworkTest(spec);else testResult(E.test(s,spec.source,spec.target,spec.protocol));};$('createVm').onclick=()=>{if(controlCenter){const access=controlCenter.vmAccess($('vmHost').value);if(!access.ok){vmOutcome(access);return;}}vmOutcome(E.createVM(s,$('vmHost').value,$('vmName').value,Number($('vmRam').value),Number($('vmCpu').value),Number($('vmDisk').value),$('vmMode').value));};$('provisionCloud').onclick=()=>{const m=$('cloudModel').value,v=$('cloudService').value;if(!m||!v)return toast('Choose both a deployment and service model.',false);s.cloud.model=m;s.cloud.service=v;s.cloud.account=true;result({ok:true,message:'Learning account provisioned. '+cloudExplanation(m,v)})};$('cloudBackup').onclick=()=>{const source=E.find(s,$('cloudBackupSource')?.value||$('testSource').value);if(!source||!['server','nas'].includes(source.type))return toast('Choose a server or NAS as the backup source first.',false);const r=E.test(s,source.id,'cloud');testResult(r);if(!r.ok)return;Object.assign(s.cloud,{backup:true,verified:false,sourceName:source.name,sourceId:source.id,capacity:E.raidStatus(source).usable});renderBottom();learning?.refresh();desktop?.refresh();toast('Simulated off-site recovery copy completed.')};
function validateSave(x){
 if(!x||x.version!==1||!Object.hasOwn(missions,x.mission)||!Array.isArray(x.devices)||x.devices.length>26||!Array.isArray(x.links)||x.links.length>100||!Array.isArray(x.vms)||x.vms.length>32)throw Error('Unsupported lab file.');
 const cleanNetwork=n=>{if(!n||!['dhcp','static'].includes(n.mode))throw Error('Invalid guest network.');const out={mode:n.mode,wifi:false};for(const k of ['ip','mask','gateway','dns'])if(n[k]!==undefined){if(typeof n[k]!=='string'||n[k].length>32)throw Error('Invalid guest network value.');out[k]=n[k];}if(out.mode==='static'&&(E.ipNumber(out.ip)===null||!E.validMask(out.mask)))throw Error('Invalid guest address.');return out;};
 const cleanOS=o=>{if(o===undefined)return undefined;if(!o||typeof o!=='object'||Array.isArray(o))throw Error('Invalid OS configuration.');const out={};for(const k of ['adapterEnabled','driverInstalled','dhcpReleased','allowServices'])if(o[k]!==undefined){if(typeof o[k]!=='boolean')throw Error('Invalid OS switch.');out[k]=o[k];}if(o.hostname!==undefined){if(typeof o.hostname!=='string'||!/^(?=.{1,15}$)(?=.*[a-zA-Z])[a-zA-Z0-9](?:[a-zA-Z0-9-]*[a-zA-Z0-9])?$/.test(o.hostname))throw Error('Invalid OS hostname.');out.hostname=o.hostname;}return out;};
 const clean=E.fresh(x.mission),ids=new Set();clean.devices=[];
 const typed=(v,base)=>{if(typeof base==='number'){if(!Number.isFinite(v)||Math.abs(v)>100000)throw Error('Invalid number.');return v;}if(typeof base==='boolean'){if(typeof v!=='boolean')throw Error('Invalid switch value.');return v;}if(typeof base==='string'){if(typeof v!=='string'||v.length>200)throw Error('Invalid text value.');return v;}return base;};
 for(const d of x.devices){if(!d||!Object.hasOwn(E.catalog,d.type)||typeof d.id!=='string'||!/^[a-z]+\d{0,9}$/.test(d.id)||!new RegExp('^'+d.type+'\\d*$').test(d.id)||ids.has(d.id))throw Error('Invalid device.');ids.add(d.id);const seed=E.fresh();let base;if(['wall','isp'].includes(d.type)){base=E.find(seed,d.type);if(d.id!==d.type)throw Error('Invalid fixed endpoint.');}else base=E.find(seed,E.addDevice(seed,d.type).id);
 for(const k of Object.keys(base)){if(['network','router','services'].includes(k)){if(!d[k]||typeof d[k]!=='object')throw Error('Missing configuration.');for(const q of Object.keys(base[k]))base[k][q]=typed(d[k][q],base[k][q]);}else if(k==='ports'){for(const p of Object.keys(base.ports)){if(d.type==='switch'&&['p7','p8'].includes(p)&&d.ports&&!(p in d.ports))continue;const v=d.ports?.[p]?.vlan;if(!Number.isInteger(v)||v<1||v>4094)throw Error('Invalid VLAN.');base.ports[p].vlan=v;}}else if(k==='disks'){if(!Array.isArray(d.disks)||d.disks.length>4)throw Error('Invalid disks.');base.disks=d.disks.map(v=>{if(![1,2,4].includes(v.tb)||typeof v.failed!=='boolean')throw Error('Invalid member.');return {tb:v.tb,failed:v.failed}});}else if(k==='rack'){if(d.rack!==null&&(!E.catalog[d.type].u||!d.rails||!Number.isInteger(d.rack)||d.rack<1||d.rack+E.catalog[d.type].u-1>E.RACK_UNITS))throw Error('Invalid rack position.');base.rack=d.rack;}else base[k]=k==='rebuilds'&&d[k]===undefined?0:typed(d[k],base[k]);}
 if(!['wall','isp'].includes(base.type)){if(!['','AM4-8'].includes(base.cpu)||![0,16,32,64].includes(base.ram)||!['none','1g','10g'].includes(base.nic)||!['','Windows 11','Windows Server','Linux','NAS OS','Hypervisor'].includes(base.os)||!Number.isInteger(base.rebuilds)||base.rebuilds<0)throw Error('Invalid installed component.');if(clean.devices.filter(q=>q.type===base.type).length>=2)throw Error('Too many devices of one type.');if(base.rack!==null&&clean.devices.some(q=>q.rack!=null&&base.rack<q.rack+E.catalog[q.type].u&&q.rack<base.rack+E.catalog[base.type].u))throw Error('Saved rack devices overlap.');}if(base.network&&!['dhcp','static'].includes(base.network.mode))throw Error('Invalid IP mode.');if(base.raid&&!['0','1','5','6','10'].includes(base.raid))throw Error('Invalid RAID.');if(d.osState!==undefined)base.osState=cleanOS(d.osState);clean.devices.push(base);}
 if(!ids.has('wall')||!ids.has('isp'))throw Error('Missing endpoints.');
 clean.nextId=1000;for(const l of x.links){const r=E.connect(clean,l.a,l.ap,l.b,l.bp,l.type,l.length);if(!r.ok)throw Error('Invalid saved cable: '+r.message);clean.links.at(-1).broken=l.broken===true;}
 for(const v of x.vms){if(!E.find(clean,v.host)||E.find(clean,v.host).type!=='server'||!/^vm\d{1,9}$/.test(v.id)||ids.has(v.id)||typeof v.name!=='string'||v.name.length>32||!Number.isInteger(v.ram)||v.ram<1||v.ram>32||![1,2,4].includes(v.cpu)||!Number.isInteger(v.disk)||v.disk<10||v.disk>500||!['external','internal','private'].includes(v.mode)||!['','Linux'].includes(v.os)||typeof v.running!=='boolean'||typeof v.service!=='boolean')throw Error('Invalid VM.');ids.add(v.id);clean.vms.push({id:v.id,host:v.host,name:v.name,ram:v.ram,cpu:v.cpu,disk:v.disk,mode:v.mode,os:v.os,running:v.running,service:v.service,...(v.osState?{osState:cleanOS(v.osState)}:{}),...(v.network?{network:cleanNetwork(v.network)}:{})});}
 for(const k of Object.keys(clean.safety))clean.safety[k]=x.safety?.[k]===true;clean.outage=x.outage===true;clean.step=Number.isInteger(x.step)&&x.step>=0?Math.min(x.step,missions[x.mission].steps.length-1):0;clean.events=Array.isArray(x.events)?x.events.filter(t=>typeof t==='string').map(t=>t.slice(0,400)).slice(0,60):[];clean.view=['bench','rack','rear','network','inside'].includes(x.view)?x.view:'bench';clean.selected=ids.has(x.selected)?x.selected:null;clean.nextId=Math.max(1000,...[...ids].map(id=>Number(id.replace(/^[a-z]+/,''))||0))+200;const c=x.cloud||{};clean.cloud={model:['public','private','hybrid','community'].includes(c.model)?c.model:'',service:['iaas','paas','saas'].includes(c.service)?c.service:'',account:c.account===true,backup:c.backup===true,verified:c.verified===true,sourceName:typeof c.sourceName==='string'?c.sourceName.slice(0,100):'',sourceId:ids.has(c.sourceId)?c.sourceId:'',capacity:Number.isFinite(c.capacity)?c.capacity:0};clean.layout={};for(const view of ['bench','rear','network','world']){clean.layout[view]={};for(const [id,p] of Object.entries(x.layout?.[view]||{})){if(ids.has(id)&&Array.isArray(p)&&p.length===2&&p.every(Number.isFinite))clean.layout[view][id]=[Math.max(9,Math.min(91,p[0])),Math.max(25,Math.min(89,p[1]))];}}if(x.walkthrough&&Number.isInteger(x.walkthrough.index)&&x.walkthrough.index>=0&&x.walkthrough.index<=100)clean.walkthrough={index:x.walkthrough.index,webTest:x.walkthrough.webTest===true,serverTest:x.walkthrough.serverTest===true,vmTest:x.walkthrough.vmTest===true,courseTest:x.walkthrough.courseTest===true,degradedTest:x.walkthrough.degradedTest===true,ipTest:x.walkthrough.ipTest===true,privateVmTest:x.walkthrough.privateVmTest===true,internalVmTest:x.walkthrough.internalVmTest===true,restoredVmTest:x.walkthrough.restoredVmTest===true};if(x.desktopProgress){clean.desktopProgress={opened:x.desktopProgress.opened===true,machines:{}};for(const [id,p]of Object.entries(x.desktopProgress.machines||{})){if(!ids.has(id)||!p)continue;const texts=(v,max)=>Array.isArray(v)?[...new Set(v.filter(x=>typeof x==='string'&&/^[a-z]+$/.test(x)&&x.length<30))].slice(0,max):[];clean.desktopProgress.machines[id]={commands:texts(p.commands,10),quizzes:texts(p.quizzes,12),projects:texts(p.projects,8),page:p.page===true,workflows:texts(p.workflows,10)};}}if(x.assessment){if(typeof challengeCases==='undefined'||!Object.hasOwn(challengeCases,x.assessment.id))throw Error('Invalid challenge.');clean.assessment={id:x.assessment.id,hints:Math.max(0,Math.min(2,Number(x.assessment.hints)||0)),attempts:Math.max(0,Math.min(1000,Number(x.assessment.attempts)||0)),submitted:x.assessment.submitted===true};}return clean;
}
